const ACTION_SELECTOR_ROW_SX = {
    ...ACTION_SELECTOR_GROUP_SX,
    flexWrap: 'nowrap',
    '& .MuiToggleButtonGroup-grouped': {
        ...ACTION_SELECTOR_GROUP_SX['& .MuiToggleButtonGroup-grouped'],
