        status: 'waitingForInput'
        type: 'inputRequest'
    }
    | ActionRunEventBase & {
        status: ActionRunStatus
        type: 'run'
    }
    | ActionRunEventBase & {
        accountId?: string
        command?: string
        conversationId?: string
        runWorktree?: number | null
        message?: string | null
